// Anchor tests: run with  node tools/test_anchors.js
// These codes were generated by the exact in-page PRNG chain and verified
// against the live game (2026-10-18 -> 6101 and 2026-10-21 -> 3039/F were
// actually played end-to-end on 1in8b.life).
const OneIn8B = require('./1in8b.js');
const C = require('../data/countries.min.js');

const hk = (y, m, d) => OneIn8B.scanDate(C, y, m, d).byCountry.HKG.map(x => x.code + x.g).join(',');
const codes = (y, m, d) => OneIn8B.scanDate(C, y, m, d).byCountry.HKG.map(x => x.code).join(',');

let fail = 0;
const t = (label, got, want) => {
  const ok = got === want;
  if (!ok) fail++;
  console.log(ok ? 'PASS' : 'FAIL', label, '→', got, ok ? '' : `(want ${want})`);
};

t('2026-10-19 HKG + sex', hk(2026, 10, 19), '0543F,6307M,9227M');
t('2026-10-21 HKG + sex', hk(2026, 10, 21), '3039F');
t('2026-10-18 HKG', codes(2026, 10, 18), '6101');
t('2026-10-20 HKG', codes(2026, 10, 20), '2061,2477,3512,6344');
t('2026-10-22 HKG', codes(2026, 10, 22), '0736,3528,8980');
t('2026-10-23 HKG', codes(2026, 10, 23), '0093,8495');
t('2026-10-24 HKG', codes(2026, 10, 24), '1504,4950,7443');
t('2026-10-25 HKG', codes(2026, 10, 25), '0312,6565,9816');

// Sanity: per-date India share fluctuates around ~17.8% long-run (official site: 17.6%)
for (const [y, m, d] of [[2026, 10, 18], [2026, 10, 19], [2026, 10, 21]]) {
  const s = OneIn8B.scanDate(C, y, m, d);
  const ok = s.indPct > 17 && s.indPct < 19 && Math.abs(s.mean - 0.5) < 0.01;
  if (!ok) fail++;
  console.log(ok ? 'PASS' : 'FAIL', `sanity ${s.key}`, `IND ${s.indPct.toFixed(1)}% mean ${s.mean.toFixed(3)}`);
}

process.exit(fail ? 1 : 0);
